INSERT INTO LienHe (HoTen, SDT, Email, NoiDung, TrangThai) VALUES
  ('Vũ Đức Sơn', '0314412946', 'lienhe1@gmail.com', 'Tôi muốn thuê xe 7 chỗ tự lái đi công tác từ Hà Nội về Hải Phòng 3 ngày, xin báo giá trọn gói.', 'Đã phản hồi'),
  ('Trịnh Minh Bình', '0845252264', 'lienhe2@gmail.com', 'Thủ tục nhận xe rất nhanh gọn, nhân viên thân thiện và tư vấn nhiệt tình.', 'Mới'),
  ('Hồ Bảo Sơn', '0842191260', 'lienhe3@gmail.com', 'Cho hỏi tiền đặt cọc có được hoàn trả ngay sau khi kết thúc hợp đồng kiểm tra xe không?', 'Đã phản hồi'),
  ('Ngô Đình Hùng', '0768651223', 'lienhe4@gmail.com', 'Công ty chúng tôi cần thuê xe Fortuner theo tháng tại Đà Nẵng, có xuất hóa đơn VAT không?', 'Đã phản hồi'),
  ('Trần Phương Lan', '0873160664', 'lienhe5@gmail.com', 'Góp ý thêm: nên mở rộng thêm nhiều điểm trả xe tại các quận trung tâm Hà Nội hơn nữa.', 'Mới'),
  ('Ngô Tuấn Hải', '0883829990', 'lienhe6@gmail.com', 'Thủ tục nhận xe rất nhanh gọn, nhân viên thân thiện và tư vấn nhiệt tình.', 'Đã phản hồi'),
